def wait_shards(shards):
    live = dict(shards)
    while live:
        time.sleep(1)
        for k, s in list(live.items()):
            rc = s["proc"].poll()
            elapsed = time.monotonic() - s["t0"]
            if rc is None and elapsed > s["limit"]:
                for sig in (signal.SIGTERM, signal.SIGKILL):
                    try:
